project.solution:
import json
import math
from datetime import date

def days_left(today_text, exam_text):
    return (date.fromisoformat(exam_text) - date.fromisoformat(today_text)).days

def plan_json(subjects, today_text, exam_text):
    n = days_left(today_text, exam_text)
    return json.dumps({"days_left": n, "per_subject": math.floor(n / len(subjects))})
